(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const catalogs = window.OS_CATALOG || {docs:{},workbench:[]};
  const sections = [['today','◈','Today'],['pipeline','◎','Companies & pilots'],['approvals','✓','Decision inbox'],['work','▥','Work board'],['calendar','▦','Calendar'],['content','▤','Content studio'],['research','⌕','Research'],['experiments','◇','Experiments'],['agents','↻','Agent activity'],['library','▧','Source library'],['guide','?','Your marketing guide']];
  const stages = [['planned','Planned'],['in-progress','In progress'],['review','Ready for review'],['done','Done']];
  const kinds = ['research','follow-up','content','pilot','experiment','campaign','operations'];
  const today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const dayDate = value => new Date(`${value}T12:00:00`);
  const dateLabel = value => value ? new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(dayDate(value.slice(0,10))) : 'No date set';
  const time = value => {const d=new Date(value);return Number.isFinite(d.valueOf())?new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(d):'Not recorded';};
  const sourceAge = value => {const d=new Date(value);if(!Number.isFinite(d.valueOf()))return 'Date unknown';const days=Math.max(0,Math.floor((Date.now()-d.valueOf())/86400000));return days===0?'Updated today':`${days} day${days===1?'':'s'} old`;};
  const clip = (value, limit=180) => String(value||'').length>limit?String(value).slice(0,limit)+'…':String(value||'');
  const href = value => {if(!String(value||'').trim())return null;try{const u=new URL(value,location.href);return ['https:','http:'].includes(u.protocol)?u.href:null;}catch{return null;}};
  const sourceLink = (value,label='Open source ↗') => href(value)?`<a class="button subtle" href="${esc(href(value))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:'';
  const tag = (value,tone='neutral') => `<span class="tag ${tone}">${esc(value)}</span>`;
  const empty = (title,message) => `<div class="empty"><strong>${esc(title)}</strong>${esc(message)}</div>`;
  const state = {view:'today',approvals:[],leads:[],research:[],reports:[],tasks:[],health:{},sources:{},filter:'review',month:new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedDay:today(),loading:false,drawerVersion:0};
  const sources = [['health','/api/health',null],['approvals','/api/approvals','approvals'],['leads','/api/leads','leads'],['research','/api/research','articles'],['reports','/api/run-reports','reports'],['tasks','/api/workspace','tasks']];
  const names = {health:'Services',approvals:'Decisions',leads:'Companies',research:'Research',reports:'Agent reports',tasks:'Shared work'};
  function phase(row) {
    if(['sent','completed'].includes(row.status))return row.decision==='Approved'?'complete':'exception';
    if(['failed','manual-execution-required'].includes(row.status))return 'exception';
    if(row.status==='changes-requested'||row.decision==='Changes requested')return 'changes';
    if(row.decision==='Pending review'&&['pending','queued','approved'].includes(row.status))return 'review';
    if(row.decision==='Approved'&&['queued','running','approved'].includes(row.status))return 'execution';
    return 'exception';
  }
  const phaseName={review:'Needs your decision',execution:'Approved for execution',changes:'Revision requested',complete:'Outcome recorded',exception:'Check this record'};
  const phaseTone={review:'gold',execution:'neutral',changes:'gold',complete:'green',exception:'red'};
  const pending=()=>state.approvals.filter(x=>phase(x)==='review');
  const openTasks=()=>state.tasks.filter(x=>x.status!=='done');
  const dueTasks=()=>openTasks().filter(x=>x.due_date&&x.due_date<=today()).sort((a,b)=>a.due_date.localeCompare(b.due_date));
  function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
  function heading(title,description,action=''){return `<div class="page-heading"><div><span class="eyebrow">Averion Software · Marketing OS</span><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${action}</div>`;}
  function panel(title,description,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div>${action}</div>${body}</section>`;}
  function recordButton(type,row,title,summary,badge=''){return `<button class="row-button" data-record="${type}" data-id="${esc(row.id)}"><span><span class="row-title">${esc(title)}</span><span class="row-sub">${esc(clip(summary))}</span>${badge?`<span class="meta">${badge}</span>`:''}</span><span class="row-arrow" aria-hidden="true">↗</span></button>`;}
  function approvalRow(row){return recordButton('approval',row,row.task,row.note,tag(phaseName[phase(row)],phaseTone[phase(row)])+`<span>${esc(time(row.created_at))}</span>`);}
  function taskRow(row){return recordButton('task',row,row.title,row.notes,tag(stages.find(x=>x[0]===row.status)?.[1]||row.status,row.status==='done'?'green':'neutral')+`<span>${esc(row.due_date?dateLabel(row.due_date):'No deadline')} · ${esc(row.owner||'Unassigned')}</span>`);}
  function reportRow(row){return recordButton('report',row,row.title,row.summary,`<span>${esc(time(row.created_at))}</span>`);}
  function docs(groups){return `<div class="doc-grid">${groups.flatMap(group=>(catalogs.docs[group]||[]).map(([title,description,url,type])=>`<a class="doc-card" data-doc href="/${esc(url)}"><span class="eyebrow">${esc(type)}</span><h3 style="margin:12px 0 7px">${esc(title)}</h3><p>${esc(description)}</p><span class="row-sub">Read document ↗</span></a>`)).join('')}</div>`;}
  function recommendations(){
    const list=[];
    if(dueTasks().length)list.push(['Close the loop on due work',`${dueTasks().length} open item${dueTasks().length===1?' has':'s have'} a deadline today or earlier. Decide what to finish, reschedule, or ask for help with.`,'Open calendar','calendar']);
    if(pending().length)list.push(['Review the work waiting on you',`${pending().length} item${pending().length===1?' needs':'s need'} a decision. Read the exact draft and its evidence before approving the next step.`,'Open decision inbox','approvals']);
    if(state.leads.length)list.push(['Turn company fit into a real discovery question',`${state.leads.length} researched companies are in the shared pipeline. Fit is a reason to investigate; verify the buyer’s need, authority, timing, and baseline before proposing a pilot.`,'Inspect companies','pipeline']);
    list.push(['Choose a segment through evidence', 'Compare buyer urgency, access to a decision-maker, implementation readiness, and procurement friction. Your target segment is still open; research should resolve it.','Explore research','research']);
    return list.slice(0,4).map((x,i)=>`<div class="suggestion"><span class="rank">${i+1}</span><div><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p><button class="button" data-view="${x[3]}">${esc(x[2])} ↗</button></div></div>`).join('');
  }
  function renderToday(){
    const latest=state.reports[0];
    return `<section class="hero"><div class="hero-main"><span class="eyebrow">${esc(new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(new Date()))}</span><h1>Make your next customer<br>conversation count.</h1><p>Your workspace for choosing the right companies, preparing useful conversations, and turning evidence into pilot opportunities.</p><div class="hero-steps"><b>Understand the buyer</b><span>→</span><b>Earn a conversation</b><span>→</span><b>Prove pilot fit</b></div></div><div class="hero-side"><span class="eyebrow">Your operating focus</span><h3 style="margin-top:12px">Qualified leads & pilot customers</h3><p>Research chooses the best segment. Agents prepare the work. Publishing and outreach wait for your decision.</p><span class="tag gold">90-day target · not set yet</span><p style="margin:12px 0 0">Start with discovery evidence, then set a realistic target.</p></div></section>
    <div class="metrics"><button class="metric" data-view="approvals"><span class="metric-label">Decisions waiting</span><div class="metric-value">${!state.sources.approvals?.updated?'—':pending().length}</div><small>Exact work ready for review ↗</small></button><button class="metric" data-view="pipeline"><span class="metric-label">Researched companies</span><div class="metric-value">${!state.sources.leads?.updated?'—':state.leads.length}</div><small>Fit candidates, not confirmed buyers ↗</small></button><button class="metric" data-view="calendar"><span class="metric-label">Due today or overdue</span><div class="metric-value">${!state.sources.tasks?.updated?'—':dueTasks().length}</div><small>Open shared deadlines ↗</small></button><button class="metric" data-view="experiments"><span class="metric-label">Pilot customer results</span><div class="metric-value" style="font-size:21px">Not tracked yet</div><small>Define your measurement plan ↗</small></button></div>
    <div class="grid-two"><div class="stack">${panel('Your next best moves','Recommendations based on the available workspace records.',recommendations())}${panel('Recent agent work','Open a report to see output, QA findings, and next steps.',state.reports.slice(0,3).map(reportRow).join('')||empty('No reports loaded','Agent output will appear here when it is recorded.'),'<button class="button subtle" data-view="agents">All activity ↗</button>')}</div><div class="stack">${panel('Your decision desk',`${pending().length} items awaiting review in the loaded queue.`,pending().slice(0,3).map(approvalRow).join('')||empty('No pending decisions loaded','You can inspect approved work and exceptions in the inbox.'),'<button class="button subtle" data-view="approvals">Open inbox ↗</button>')}${panel('Coming up','Shared deadlines you have assigned.',openTasks().filter(x=>x.due_date).sort((a,b)=>a.due_date.localeCompare(b.due_date)).slice(0,4).map(taskRow).join('')||empty('Build your first timeline','Add a discovery, research, or pilot task and choose a deadline. The calendar is shared across the workspace.'),'<button class="button subtle" data-new>＋ Add</button>')}${panel('Know what is current','Freshness is part of the evidence.',`<p class="row-sub">Latest recorded agent activity: <strong>${esc(latest?time(latest.created_at):'Not available')}</strong></p><p class="row-sub">Company evidence: ${esc(state.leads[0]?sourceAge(state.leads[0].updated_at):'No company records loaded')}.</p><div class="explainer">A synced dashboard means the records loaded successfully. It does not mean the research itself is recent.</div>`)}</div></div>`;
  }
  function renderPipeline(){return heading('Companies worth a conversation','Inspect the evidence, understand the gaps, and plan the next step toward a qualified pilot.')+`<div class="explainer"><strong>How to decide:</strong> a fit score is a research signal. Before calling a company sales-qualified, confirm a real problem, a person who can act, a timeline, and a measurable starting point.</div><div class="account-grid">${state.leads.map(row=>`<button class="account-card" data-record="lead" data-id="${row.id}"><span class="monogram">${esc(row.company.split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</span><h3>${esc(row.company)}</h3><p>${esc(row.segment)}</p>${tag(row.disposition==='qualified'?'Fit-qualified research':row.disposition,'gold')}<p style="margin:12px 0 0">${esc(clip(row.next_action,150))}</p><div class="score"><span>Research fit · ${Math.max(0,Math.min(100,Number(row.fit_score)||0))}/100</span><span>Open dossier ↗</span></div><div class="score-track"><span style="width:${Math.max(0,Math.min(100,Number(row.fit_score)||0))}%"></span></div><div class="meta">${esc(sourceAge(row.updated_at))}</div></button>`).join('')}</div>${!state.leads.length?empty('No companies loaded','Company research will appear here when the shared pipeline receives records.'):''}<div class="section-space">${panel('Pilot qualification resources','Use these to turn an interested company into a bounded, measurable pilot.',docs(['pipeline']))}</div>`;}
  function renderApprovals(){
    const filters=[['review','Needs decision'],['execution','Approved'],['changes','Revisions'],['exception','Exceptions'],['complete','Outcomes'],['all','All recent']];
    const rows=state.approvals.filter(x=>state.filter==='all'||phase(x)===state.filter);
    return heading('Your decision inbox','Open the exact work, understand what happens next, and record your decision.')+`<div class="toolbar tabs">${filters.map(([id,label])=>`<button data-filter="${id}" class="${state.filter===id?'selected':''}">${esc(label)} · ${state.approvals.filter(x=>id==='all'||phase(x)===id).length}</button>`).join('')}</div>${panel(filters.find(x=>x[0]===state.filter)?.[1]||'Decisions','Counts reflect the most recent 100 queue records returned by the service.',rows.map(approvalRow).join('')||empty('Nothing in this category','Choose another category to inspect the rest of the queue.'))}`;
  }
  function taskCard(row){return `<button class="task-card" data-record="task" data-id="${row.id}">${tag(row.kind)}<h3>${esc(row.title)}</h3><p>${esc(clip(row.notes,105))}</p><div class="meta">${row.due_date?tag(dateLabel(row.due_date),row.status!=='done'&&row.due_date<today()?'red':'neutral'):tag('No deadline')}<span>${esc(row.owner||'Unassigned')}</span></div></button>`;}
  function board(rows){return `<div class="board">${stages.map(([id,label])=>`<section class="lane"><div class="lane-head"><span>${label}</span><span>${rows.filter(x=>x.status===id).length}</span></div>${rows.filter(x=>x.status===id).map(taskCard).join('')||'<p class="row-sub" style="padding:12px">No work in this stage.</p>'}</section>`).join('')}</div>`;}
  function renderWork(){return heading('The work, moving forward','Open a card to change its stage, assign an owner, set a deadline, or keep notes. All changes are shared.','<button class="button primary" data-new>＋ Plan work</button>')+board(state.tasks)+`<div class="explainer">This board tracks plans and outcomes. Adding a card does not start an agent or send a message. Available preparation workflows are in <button class="button subtle" data-view="agents">Agent activity ↗</button></div>`;}
  function renderCalendar(){
    const month=state.month,first=new Date(month.getFullYear(),month.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());
    let days='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const tasks=state.tasks.filter(x=>x.due_date===key);days+=`<button class="day ${d.getMonth()!==month.getMonth()?'outside':''} ${key===today()?'today':''} ${key===state.selectedDay?'selected':''}" data-day="${key}" aria-label="${esc(dateLabel(key))}, ${tasks.length} tasks" aria-pressed="${key===state.selectedDay}"><span class="day-number">${d.getDate()}</span>${tasks.slice(0,2).map(x=>`<span class="calendar-task ${x.status==='done'?'done':key<today()?'overdue':''}">${esc(x.title)}</span>`).join('')}${tasks.length>2?`<span class="calendar-task more">+${tasks.length-2} more</span>`:''}</button>`;}
    const selected=state.tasks.filter(x=>x.due_date===state.selectedDay);
    return heading('A calendar you can act on','Select a day to see its work or add a deadline. Dates are the shared calendar dates you assign.')+`<div class="calendar-layout"><section class="panel"><div class="calendar-head"><h2>${esc(new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(month))}</h2><div class="top-actions"><button class="button" data-month="-1" aria-label="Previous month">←</button><button class="button" data-month="0">Today</button><button class="button" data-month="1" aria-label="Next month">→</button></div></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="weekday">${x}</div>`).join('')}${days}</div><p class="row-sub" style="margin-top:14px">Gold: scheduled · Red: overdue · Green: done. Agent run timestamps appear in Agent activity, not as invented deadlines.</p></section><div class="stack">${panel(dateLabel(state.selectedDay),'Selected day',selected.map(taskRow).join('')||empty('Room to make progress','Plan a research checkpoint, a follow-up, or a pilot decision.'),'<button class="button subtle" data-new data-date="'+state.selectedDay+'">＋ Add</button>')}${panel('Unscheduled work','Give these items a useful checkpoint.',openTasks().filter(x=>!x.due_date).slice(0,6).map(taskRow).join('')||empty('No unscheduled tasks','New work without a date will appear here.'))}</div></div>`;
  }
  function renderResearch(){return heading('Understand the market. Choose your move.','Read the finding, the source, and what it could mean for your next campaign or customer conversation.')+`<div class="research-grid">${state.research.map(row=>`<button class="research-card" data-record="research" data-id="${row.id}">${tag(row.confidence,'gold')}<h3>${esc(row.title)}</h3><p>${esc(clip(row.finding,210))}</p><div class="meta"><span>${esc(row.session_date)}</span><span>${row.source_url?'Source linked':'Source note only'} ↗</span></div></button>`).join('')}</div><div class="section-space">${docs(['research'])}</div>`;}
  function renderContent(){return heading('Content with a purpose','Prepare a useful message for a specific buyer, connect its evidence, and review the exact copy before publishing.')+`<div class="grid-two"><div class="stack">${panel('Publishing decisions','Content awaiting a decision or revision.',state.approvals.filter(x=>['social-publish','social-engage','publish'].includes(x.action)&&['review','changes'].includes(phase(x))).map(approvalRow).join('')||empty('No content decisions loaded','Drafts submitted for review will appear here.'))}</div>${panel('A useful content brief','Give every asset a job in the customer journey.',`<div class="guide-step"><h3>Who is it for?</h3><p>Name the buyer and the specific operating problem.</p></div><div class="guide-step"><h3>What makes it credible?</h3><p>Attach a source or approved product proof for every factual claim.</p></div><div class="guide-step"><h3>What is the next step?</h3><p>Offer a useful discovery question, demo, or bounded pilot discussion.</p></div><div class="dialog-actions"><button class="button primary" data-new data-kind="content">Plan content</button></div>`)}</div><div class="section-space">${board(state.tasks.filter(x=>x.kind==='content'))}</div><div class="section-space">${docs(['content'])}</div>`;}
  function renderExperiments(){return heading('Learn your way to pilot customers','Keep the hypothesis, success measure, evidence, and next decision together. A pilot is an opportunity to prove value.')+`<div class="grid-equal">${panel('Choose a practical first experiment','Suggested structure; no performance result is implied.',`<span class="eyebrow">Segment discovery</span><h3 style="margin-top:10px">Which buyers have a problem we can help solve now?</h3><p class="row-sub">Compare a small, researched set of operator segments on urgency, buyer access, workflow fit, and the effort needed to start a pilot.</p><div class="explainer">Measure qualified discovery conversations and the evidence learned. Set the numerical target after the first baseline is available.</div><button class="button" data-new data-kind="experiment">Create an experiment brief</button>`)}${panel('A pilot needs a clear agreement','Use this checklist before proposing one.',`<div class="guide-step"><h3>Scope & readiness</h3><p>Properties, users, workflow, data needs, owner, and a feasible starting date.</p></div><div class="guide-step"><h3>Measure before and after</h3><p>Choose one or two operating metrics, capture a baseline, and set a review checkpoint.</p></div><div class="guide-step"><h3>Define the next decision</h3><p>Agree how evidence will inform continuing, changing, or ending the pilot. Commercial terms require your approval.</p></div><div class="dialog-actions"><button class="button" data-new data-kind="pilot">Plan a pilot checkpoint</button></div>`)}</div><div class="section-space">${board(state.tasks.filter(x=>['pilot','experiment','campaign'].includes(x.kind)))}</div><div class="section-space">${docs(['experiments'])}</div>`;}
  function renderAgents(){return heading('Know what the agents actually did','Inspect the output and quality findings. A completed run is separate from a published message or customer result.')+`<div class="grid-two"><div>${panel('Run history','Most recent 30 recorded runs. Open any report for its complete available details.',state.reports.map(reportRow).join('')||empty('No run reports loaded','Reports appear when the runner records them in the shared workspace.'))}</div><div class="stack">${panel('Prepare work','These are the existing supported agent workflows.',catalogs.workbench.map((x,i)=>`<div class="guide-step"><h3>${esc(x.task)}</h3><p>${esc(x.about)}</p><button class="button" style="margin-top:12px" data-workflow="${i}">Queue preparation ↗</button></div>`).join(''))}${panel('Connection status','Configuration is not a delivery test.',`<p class="row-sub">Email credentials: ${state.health.zohoConfigured?'Configured':'Not confirmed'}</p><p class="row-sub">Publishing: approval required; delivery is confirmed by the publishing service.</p><div class="explainer">A local runner must be online to execute preparation work. This screen reports recorded activity; it cannot prove the runner is currently online.</div>`)}${docs(['schedule'])}</div></div>`;}
  function renderGuide(){return heading('Your marketing decision guide','A practical way to use the workspace when marketing is new to you.')+`<div class="grid-equal">${panel('Start with the customer','Use the OS in this order.',`<div class="guide-step"><h3>1. Understand a costly problem</h3><p>Research identifies who experiences it, how they handle it today, and why change might matter.</p></div><div class="guide-step"><h3>2. Qualify a conversation</h3><p>A company can look like a fit without being ready to buy. Confirm need, decision process, timing, and measurable pain.</p></div><div class="guide-step"><h3>3. Prepare something useful</h3><p>Use a clear question, relevant evidence, and a specific next step. Open the exact draft in the decision inbox.</p></div><div class="guide-step"><h3>4. Learn before expanding</h3><p>Record what happened, compare it to the hypothesis, and choose what to change. A pilot needs an owner, scope, baseline, and review date.</p></div>`)}${panel('What the labels mean','Use these distinctions when deciding.',`<div class="guide-step"><h3>Fit-qualified ≠ interested</h3><p>Fit is a research assessment. Interest requires a real signal from the company.</p></div><div class="guide-step"><h3>Approved ≠ sent</h3><p>Approval records your decision. Execution and delivery are separate events.</p></div><div class="guide-step"><h3>Run complete ≠ goal achieved</h3><p>An agent may finish a draft that still fails quality review. Inspect its output.</p></div><div class="guide-step"><h3>Synced ≠ current evidence</h3><p>Data can load successfully while the underlying source is old. Check the date.</p></div><div class="guide-step"><h3>What should I measure?</h3><p>Begin with useful discovery conversations, demos, and pilot readiness. Set a numeric target once you know the starting point. Activity counts alone do not establish growth.</p></div>`)}</div>`;}
  function render(){
    $('navigation').innerHTML=sections.map(([id,icon,title])=>`<button class="nav-button ${id===state.view?'active':''}" data-view="${id}" ${id===state.view?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${esc(title)}${id==='approvals'&&pending().length?`<span class="nav-badge">${pending().length}</span>`:''}</button>`).join('');
    $('crumb').textContent=sections.find(x=>x[0]===state.view)?.[2]||'Today';
    const failures=Object.entries(state.sources).filter(([,x])=>x.ok===false);
    $('connection').innerHTML=(failures.length?`<div class="warning">${failures.map(([key])=>esc(names[key])).join(', ')} could not refresh. Previously loaded records remain visible. Use Refresh to retry.</div>`:'')+`<div class="source-status">${Object.entries(state.sources).map(([key,value])=>`<span class="${!value.ok?'stale':''}" title="${esc(value.updated?time(value.updated):'No successful load')}">${esc(names[key])} · ${value.ok?'synced':value.updated?'stale':'unavailable'}</span>`).join('')}</div>`;
    const views={today:renderToday,pipeline:renderPipeline,approvals:renderApprovals,work:renderWork,calendar:renderCalendar,research:renderResearch,content:renderContent,experiments:renderExperiments,agents:renderAgents,guide:renderGuide,library:()=>heading('Everything behind the decisions','Searchable source documents, approved positioning, evidence, and operating references.')+docs(Object.keys(catalogs.docs))};
    $('view').innerHTML=(views[state.view]||renderToday)();
    $('sync-time').textContent=state.lastRefresh?'Last refresh attempt '+time(state.lastRefresh):'Connecting to the shared workspace…';
  }
  function navigate(view){if(!sections.some(x=>x[0]===view))return;state.view=view;location.hash=view;render();window.scrollTo({top:0});}
  async function refresh(){
    if(state.loading)return;state.loading=true;$('refresh').disabled=true;
    await Promise.allSettled(sources.map(async([key,url,field])=>{
      const previous=state.sources[key]||{};
      try{const response=await fetch(url,{cache:'no-store',headers:{Accept:'application/json'},signal:AbortSignal.timeout(15000)});if(!response.ok)throw new Error('Unavailable');const data=await response.json();if(field&&!Array.isArray(data[field]))throw new Error('Invalid data');if(!field&&data.ok!==true)throw new Error('Service unavailable');state[key]=field?data[field]:data;state.sources[key]={ok:true,updated:new Date().toISOString()};}
      catch{state.sources[key]={...previous,ok:false};}
    }));state.loading=false;state.lastRefresh=new Date().toISOString();$('refresh').disabled=false;render();
  }
  function showDetail(kind,title,html){state.drawerVersion++;$('detail-kind').textContent=kind;$('detail-content').innerHTML=`<h2 id="detail-title">${esc(title)}</h2>${html}`;if(!$('detail-dialog').open)$('detail-dialog').showModal();$('detail-dialog').scrollTop=0;}
  function linkedTasks(type,id){const rows=state.tasks.filter(x=>x.linked_type===type&&String(x.linked_id)===String(id));return rows.length?`<h3>Related work & deadlines</h3>${rows.map(taskRow).join('')}`:'';}
  function planButton(type,row,kind='research'){return `<button class="button primary" data-plan="${type}" data-id="${row.id}" data-kind="${kind}">Plan next step ＋</button>`;}
  function openRecord(type,id){
    if(type==='approval'){openApproval(id);return;}
    const key={lead:'leads',research:'research',report:'reports',task:'tasks'}[type];const row=state[key]?.find(x=>String(x.id)===String(id));if(!row){toast('This record is not loaded. Refresh and try again.');return;}
    if(type==='task'){taskForm(row);return;}
    if(type==='lead')showDetail('Company dossier',row.company,`<div class="source-line">${tag(row.disposition,'gold')}<span>Research fit ${esc(row.fit_score)}/100</span><span>${esc(sourceAge(row.updated_at))}</span></div><div class="info-grid"><div class="info-cell"><small>Segment</small>${esc(row.segment||'Not recorded')}</div><div class="info-cell"><small>Recorded review status</small>${esc(row.approval_status)}</div></div><h3>Why this company is on the list</h3><p class="readable">${esc(row.evidence||'Evidence has not been attached.')}</p><h3>Recommended next step from the record</h3><p class="readable">${esc(row.next_action||'Define a focused research question.')}</p><div class="explainer"><strong>What is still unverified?</strong> The current record does not establish buyer interest, authority, urgency, budget, or a pilot baseline. Gather these before treating the account as sales-qualified.</div><h3>Discovery questions to prepare</h3><p class="readable">Which workflow is causing the most friction?\nWho owns the decision to change it?\nWhat would make a pilot worth the effort?\nWhat starting metric can both sides measure?</p>${linkedTasks(type,id)}<div class="dialog-actions">${sourceLink(row.website,'Company website ↗')}${planButton(type,row,'follow-up')}</div>`);
    if(type==='research')showDetail('Research dossier',row.title,`<div class="source-line">${tag(row.confidence,'gold')}<span>${esc(row.session_date)}</span></div><p class="readable">${esc(row.dek)}</p><h3>What was found</h3><p class="readable">${esc(row.finding)}</p><h3>What it could mean for your marketing</h3><p class="readable">${esc(row.advantage)}</p><h3>Evidence & limitations</h3><p class="readable">${esc(row.source_label||'No source label recorded.')}</p><div class="explainer">${row.source_url?'Check the source date and context before applying this finding. A confidence label is the researcher’s assessment, not proof of a market-wide result.':'This record has a source note but no direct source URL. Resolve the evidence gap before using it as a published factual claim.'}</div>${linkedTasks(type,id)}<div class="dialog-actions">${sourceLink(row.source_url)}${planButton(type,row,'experiment')}</div>`);
    if(type==='report')showDetail('Agent run report',row.title,`<div class="source-line">${esc(time(row.created_at))}<span>Run ${esc(row.run_key)}</span></div><h3>Summary</h3><p class="readable">${esc(row.summary)}</p><h3>Work completed</h3><p class="readable">${esc(row.work_done)}</p><h3>Outputs & quality findings</h3><div class="preview">${esc(row.outputs||'No output details recorded.')}</div><h3>Next action</h3><p class="readable">${esc(row.next_action||'No next action recorded.')}</p>${linkedTasks(type,id)}<div class="dialog-actions">${planButton(type,row,'operations')}</div>`);
  }
  async function openApproval(id){
    showDetail('Decision inbox','Loading the exact record…','<p class="muted">Retrieving the current draft and decision state.</p>');const ticket=state.drawerVersion;
    try{const res=await fetch(`/api/approval-detail/${encodeURIComponent(id)}`,{cache:'no-store',signal:AbortSignal.timeout(15000)});const data=await res.json();if(!res.ok)throw new Error(data.error||'Could not open this record.');if(ticket!==state.drawerVersion||!$('detail-dialog').open)return;const row=data.approval;state.currentApproval=row;const mode=phase(row),ended=['completed','sent','running'].includes(row.status);const isTest=/test only|test approval|safety pipeline test/i.test(row.task+' '+row.note);const requiresPreview=['social-publish','social-engage','outreach'].includes(row.action);const canApprove=!ended&&!isTest&&(!requiresPreview||row.publish_preview)&&mode!=='execution';
      showDetail('Decision inbox',row.task,`<div class="source-line">${tag(phaseName[mode],phaseTone[mode])}<span>${esc(row.action)} · ${esc(time(row.created_at))}</span></div><h3>Context & review notes</h3><p class="readable">${esc(row.note||'No context recorded.')}</p>${row.action==='outreach'?`<div class="info-grid"><div class="info-cell"><small>Recipient</small>${esc(row.recipient)}</div><div class="info-cell"><small>Subject</small>${esc(row.subject)}</div></div>`:''}<h3>${requiresPreview?'Exact content preview':'Recorded artifact'}</h3><div class="preview">${esc(row.publish_preview||row.content||'No preview is attached. Request the missing draft before approving external work.')}</div>${row.action==='social-publish'&&row.content?`<details style="margin-top:16px"><summary>Full source artifact, evidence & recorded checks</summary><div class="preview" style="margin-top:12px">${esc(row.content)}</div></details>`:''}${row.result?`<h3>Recorded outcome</h3><p class="readable">${esc(row.result)}</p>`:''}<div class="explainer"><strong>What happens when you approve?</strong> Your decision is recorded on this item. Preparation work enters the runner queue. Publishing and outreach are marked approved for the configured execution workflow; approval by itself does not confirm delivery.${isTest?' This is a test record and cannot be approved for execution here.':''}</div>${!ended?`<form id="decision-form"><div class="field"><label for="decision-note">Decision note · explain the change or next step</label><textarea id="decision-note" name="note" placeholder="What should happen next, and why?"></textarea></div>${row.action==='outreach'?'<label class="check-label"><input type="checkbox" name="suppressionChecked"> I checked the suppression list for this recipient and reviewed the opt-out path.</label>':''}<div id="decision-error" class="form-error" role="alert"></div><div class="dialog-actions"><button class="button" type="submit" name="decision" value="Changes requested">Request changes</button><button class="button primary" type="submit" name="decision" value="Approved" ${canApprove?'':'disabled'}>Approve for execution</button></div></form>`:''}${linkedTasks('approval',id)}`);
    }catch(error){if(ticket===state.drawerVersion)showDetail('Decision inbox','Could not open this item',empty('The record was not changed',error.message));}
  }
  function taskForm(row={},prefill={}){
    const data={kind:'research',status:'planned',title:'',due_date:'',owner:'',notes:'',linked_type:'',linked_id:'',...row,...prefill};state.editTask=data;
    const placeholder=data.kind==='experiment'?'Hypothesis:\nAudience:\nAction:\nSuccess measure:\nEvidence needed:\nReview decision:':data.kind==='pilot'?'Problem and owner:\nPilot scope:\nBaseline metric:\nSuccess criteria:\nReadiness gaps:\nNext checkpoint:':'Why this matters:\nEvidence / sources:\nNext action:\nWhat done looks like:';
    showDetail(row.id?'Shared work':'Plan work',row.id?row.title:'Give the next step a home',`<p class="row-sub">Saved to the shared board and calendar. Planning a task does not trigger outreach or publishing.</p><form id="task-form"><div class="field"><label for="task-title">Title</label><input id="task-title" name="title" required maxlength="240" value="${esc(data.title)}" placeholder="e.g. Compare pilot readiness across two segments"></div><div class="field-pair"><div class="field"><label for="task-kind">Type</label><select id="task-kind" name="kind">${kinds.map(x=>`<option ${x===data.kind?'selected':''} value="${x}">${esc(x)}</option>`).join('')}</select></div><div class="field"><label for="task-status">Stage</label><select id="task-status" name="status">${stages.map(([id,label])=>`<option ${id===data.status?'selected':''} value="${id}">${label}</option>`).join('')}</select></div></div><div class="field-pair"><div class="field"><label for="task-date">Due date</label><input id="task-date" name="due_date" type="date" value="${esc(data.due_date)}"></div><div class="field"><label for="task-owner">Owner</label><input id="task-owner" name="owner" maxlength="120" value="${esc(data.owner)}" placeholder="Person or responsible team"></div></div><div class="field"><label for="task-notes">Brief, evidence & progress notes</label><textarea id="task-notes" name="notes" maxlength="6000" style="min-height:190px" placeholder="${esc(placeholder)}">${esc(data.notes)}</textarea></div>${data.linked_type?`<p class="row-sub">Linked to ${esc(data.linked_type)} #${esc(data.linked_id)}. The original evidence stays attached.</p>`:''}<div id="task-error" class="form-error" role="alert"></div><div class="dialog-actions"><button class="button" type="button" data-close>Cancel</button><button class="button primary" type="submit">${row.id?'Save changes':'Create shared task'}</button></div></form>`);
  }
  function searchResults(query){
    const q=query.trim().toLowerCase();const rows=[];
    for(const [type,key,title,summary] of [['lead','leads','company','next_action'],['research','research','title','finding'],['report','reports','title','summary'],['approval','approvals','task','note'],['task','tasks','title','notes']])for(const r of state[key])rows.push({type,id:r.id,title:r[title]||'Untitled',summary:r[summary]||''});
    for(const items of Object.values(catalogs.docs))for(const [title,summary,url] of items)rows.push({type:'document',title,summary,url});
    const filtered=rows.filter(x=>!q||`${x.title} ${x.summary} ${x.type}`.toLowerCase().includes(q)).slice(0,35);
    $('search-results').innerHTML=filtered.length?filtered.map(x=>x.type==='document'?`<a class="search-result" data-doc href="/${esc(x.url)}"><span>${esc(x.title)}<small>${esc(clip(x.summary,130))}</small></span>${tag('document')}</a>`:`<button class="search-result" data-record="${x.type}" data-id="${esc(x.id)}"><span>${esc(x.title)}<small>${esc(clip(x.summary,130))}</small></span>${tag(x.type)}</button>`).join(''):empty('No matching records','Try a company, topic, task, or source document. Search covers loaded records and the source index.');
  }
  function closeDialogs(){state.drawerVersion++;$('detail-dialog').close();$('search-dialog').close();}
  document.addEventListener('click',event=>{
    const target=event.target.closest('button,a');if(!target)return;
    if(target.tagName==='A'&&!target.hasAttribute('data-raw-file')){try{if(new URL(target.href,location.href).pathname.toLowerCase().endsWith('.md')){closeDialogs();return;}}catch{}}
    if(target.hasAttribute('data-doc')){closeDialogs();return;}
    if(target.dataset.view){navigate(target.dataset.view);return;}
    if(target.hasAttribute('data-close')){closeDialogs();return;}
    if(target.dataset.record){$('search-dialog').close();openRecord(target.dataset.record,target.dataset.id);return;}
    if(target.hasAttribute('data-new')){taskForm({}, {kind:target.dataset.kind||'research',due_date:target.dataset.date||''});return;}
    if(target.dataset.plan){const type=target.dataset.plan;const key={lead:'leads',research:'research',report:'reports',approval:'approvals'}[type];const row=state[key]?.find(x=>String(x.id)===target.dataset.id);if(row)taskForm({}, {title:`Next step: ${clip(row.company||row.title||row.task,200)}`,kind:target.dataset.kind||'research',linked_type:type,linked_id:String(row.id),notes:row.next_action||row.advantage||''});return;}
    if(target.dataset.filter){state.filter=target.dataset.filter;render();return;}
    if(target.dataset.day){state.selectedDay=target.dataset.day;render();return;}
    if(target.hasAttribute('data-month')){const n=Number(target.dataset.month);state.month=n?new Date(state.month.getFullYear(),state.month.getMonth()+n,1):new Date(new Date().getFullYear(),new Date().getMonth(),1);if(!n)state.selectedDay=today();render();return;}
    if(target.hasAttribute('data-workflow')){
      const item=catalogs.workbench[Number(target.dataset.workflow)];if(!item)return;state.currentWorkflow=item;showDetail('Agent preparation',item.task,`<p class="readable">${esc(item.about)}</p><div class="explainer">This queues an existing preparation workflow for the local runner. It creates a draft for review. It does not publish, send outreach, or set commercial terms.</div><div id="workflow-error" class="form-error" role="alert"></div><form id="workflow-form"><div class="dialog-actions"><button class="button primary" type="submit">Queue preparation</button></div></form>`);return;
    }
  });
  document.addEventListener('submit',async event=>{
    const form=event.target;if(!['task-form','decision-form','workflow-form'].includes(form.id))return;event.preventDefault();
    const button=event.submitter;if(!button||button.disabled)return;button.disabled=true;
    const fields=Object.fromEntries(new FormData(form));let url,method='POST',body,errorId;
    if(form.id==='task-form'){const row=state.editTask;url=row.id?`/api/workspace/${row.id}`:'/api/workspace';method=row.id?'PATCH':'POST';body={...fields,linked_type:row.linked_type,linked_id:row.linked_id,...(row.id?{version:row.version}:{})};errorId='task-error';}
    if(form.id==='decision-form'){const row=state.currentApproval;url=`/api/decisions/${row.id}`;body={decision:button.value,note:fields.note,expected_status:row.status,expected_decision:row.decision,suppressionChecked:fields.suppressionChecked==='on'};errorId='decision-error';if(body.decision==='Changes requested'&&!body.note.trim()){$(errorId).textContent='Explain what needs to change so the next draft is useful.';button.disabled=false;return;}}
    if(form.id==='workflow-form'){url='/api/approvals';body={task:state.currentWorkflow.task,action:'workbench',decision:'Approved',note:'Preparation requested from Marketing OS. Draft only; external actions require approval.',recipient:'',subject:'',content:''};errorId='workflow-error';}
    try{const response=await fetch(url,{method,headers:{'content-type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(20000)});const data=await response.json();if(!response.ok)throw new Error(data.error||'The change could not be saved.');closeDialogs();toast(form.id==='task-form'?'Shared work saved.':form.id==='decision-form'?'Decision recorded on the original item.':'Preparation queued for the runner.');await refresh();}
    catch(error){if($(errorId))$(errorId).textContent=error.name==='TimeoutError'?'The response timed out. Refresh before trying again to check whether it saved.':error.message;}
    finally{button.disabled=false;}
  });
  $('refresh').addEventListener('click',refresh);
  function openSearch(){searchResults('');$('global-search').value='';$('search-dialog').showModal();$('global-search').focus();}
  $('open-search').addEventListener('click',openSearch);$('global-search').addEventListener('input',e=>searchResults(e.target.value));
  document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();closeDialogs();openSearch();}});
  for(const id of ['detail-dialog','search-dialog'])$(id).addEventListener('click',event=>{if(event.target===$(id)){const r=$(id).getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialogs();}});
  window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(sections.some(x=>x[0]===view)&&state.view!==view){state.view=view;render();}});
  const initial=location.hash.slice(1);if(sections.some(x=>x[0]===initial))state.view=initial;
  render();refresh();setInterval(()=>{if(!document.hidden&&!$('detail-dialog').open&&!$('search-dialog').open&&!$('markdown-viewer').classList.contains('open'))refresh();},90000);
})();
